const configLoader = global.get('configLoader');
const configDir = env.get('XTREAM_CONFIG_DIR') || '/home/pi/.node-red/xtream-filter/config';
try {
    const { config, filters } = configLoader.loadAll(configDir);
    global.set('xtreamConfig', config);
    global.set('filterRules', filters);
    node.status({ fill: 'green', shape: 'dot', text: 'config chargée' });
} catch (err) {
    node.error('Erreur chargement config: ' + err.message, msg);
    node.status({ fill: 'red', shape: 'ring', text: 'erreur config' });
    return null;
}
return msg;

const xtreamClient = global.get('xtreamClient');
const cfg = global.get('xtreamConfig');
msg.url = xtreamClient.playerApiUrl(cfg.source, 'get_live_categories');
msg.method = 'GET';
return msg;

const xtreamClient = global.get('xtreamClient');
const cfg = global.get('xtreamConfig');
msg.liveCategoriesRaw = Array.isArray(msg.payload) ? msg.payload : [];
msg.url = xtreamClient.playerApiUrl(cfg.source, 'get_live_streams');
msg.method = 'GET';
return msg;

const filterEngine = global.get('filterEngine');
const rules = global.get('filterRules') || {};
const categories = msg.liveCategoriesRaw || [];
const streams = Array.isArray(msg.payload) ? msg.payload : [];
const result = filterEngine.filterContent(categories, streams, rules.live || {});
global.set('liveCategories', result.categories);
global.set('liveStreams', result.items);
global.set('liveLastRefresh', Date.now());
node.status({ fill: 'green', shape: 'dot', text: result.items.length + ' chaînes / ' + result.categories.length + ' catégories' });
return null;

