const cfg = global.get('xtreamConfig') || {};
const src = cfg.source || {};
const q = (msg.req && msg.req.query) || {};
const now = Math.floor(Date.now() / 1000);
msg.payload = {
    user_info: {
        username: q.username,
        password: q.password,
        message: '',
        auth: 1,
        status: 'Active',
        exp_date: null,
        is_trial: '0',
        active_cons: '0',
        created_at: null,
        max_connections: '1',
        allowed_output_formats: ['m3u8', 'ts'],
    },
    server_info: {
        url: src.host,
        port: String(src.port || 80),
        https_port: String(src.httpsPort || src.port || 443),
        server_protocol: src.https ? 'https' : 'http',
        rtmp_port: '0',
        timezone: cfg.timezone || 'Europe/Paris',
        timestamp_now: now,
        time_now: new Date().toISOString(),
    },
};
return msg;

