const cfg = global.get('xtreamConfig') || {};
const src = cfg.source || {};
const proto = src.https ? 'https' : 'http';
const port = src.port ? ':' + src.port : '';
const items = global.get('liveStreams') || [];
const cats = global.get('liveCategories') || [];
const catMap = {};
cats.forEach((c) => { catMap[String(c.category_id)] = c.category_name; });
const lines = ['#EXTM3U'];
items.forEach((it) => {
    const group = catMap[String(it.category_id)] || '';
    const logo = it.stream_icon || '';
    const streamUrl = `${proto}://${src.host}${port}/live/${src.username}/${src.password}/${it.stream_id}.ts`;
    lines.push(`#EXTINF:-1 tvg-id="${it.epg_channel_id || ''}" tvg-logo="${logo}" group-title="${group}",${it.name}`);
    lines.push(streamUrl);
});
msg.payload = lines.join('\n');
msg.headers = { 'Content-Type': 'application/x-mpegurl' };
return msg;

msg.statusCode = 401;
msg.payload = 'Unauthorized';
